/** @type {import('tailwindcss').Config} */

// Theming (dark/light): these palettes read CSS variables from src/styles/theme.css
// (generated by scripts/generate-theme-css.mjs). Light mode inverts each scale.
// Anything that must keep its real colour in both themes (piano keys, diagram
// panels) uses arbitrary hex values such as bg-[#ffffff], which are not remapped.
const THEMED = ['slate', 'violet', 'amber', 'rose', 'emerald', 'cyan', 'sky', 'fuchsia', 'purple', 'red', 'teal', 'orange', 'indigo'];
const SHADES = ['50', '100', '200', '300', '400', '500', '600', '700', '800', '900', '950'];
const v = (name) => `rgb(var(--c-${name}) / <alpha-value>)`;

const themed = Object.fromEntries(
  THEMED.map((name) => [name, Object.fromEntries(SHADES.map((s) => [s, v(`${name}-${s}`)]))]),
);

export default {
  content: ['./index.html', './src/**/*.{js,ts,jsx,tsx}'],
  theme: {
    extend: {
      colors: {
        ...themed,
        white: v('white'),
        black: v('black'),
        muz: {
          bg: v('muz-bg'),
          panel: v('muz-panel'),
          panelStrong: v('muz-panel-strong'),
          sidebar: v('muz-sidebar'),
          accent: v('muz-accent'),
          accentStrong: v('muz-accent-strong'),
          warning: '#ffb454',
          danger: '#ff5d73',
          text: v('muz-text'),
          muted: v('muz-muted'),
        },
      },
      boxShadow: {
        glow: '0 0 25px rgba(115, 224, 169, 0.28)',
      },
    },
  },
  plugins: [],
};
